def topup_for(chapter_file: str) -> list[str]:
    ch = chapter_file.split('-')[0]
    sweets = ['分半颗糖', '两杯豆浆', '蹭袖口', '系鞋带', '占座', '抄公式', '修铅笔', '共伞']
    themes = {
        "00": ('序', '发送失败', '空位'),
        "01": ('发送失败', '空位', '赵宜家'),
        "02": ('空位', '赵宜家', '胡同'),
        "03": ('赵宜家', '胡同', '第三夜'),
        "04": ('胡同', '第三夜', '胡同深'),
        "05": ('第三夜', '胡同深', '便利店'),
        "06": ('胡同深', '便利店', '天桥'),
        "07": ('便利店', '天桥', '西单'),
        "08": ('天桥', '西单', '食街'),
        "09": ('西单', '食街', '三楼'),
        "10": ('食街', '三楼', '倒带馆'),
        "11": ('三楼', '倒带馆', '停止'),
    }
    t = themes.get(ch, ("", "", ""))
    locs = ["第三排靠窗", "电信营业厅", "派出所", "赵宜家厨房", "护城河", "小卖部", "大韦家", "西单围挡", "修鞋铺", "广播室"]
    out = []
    for i in range(200):
        loc = locs[i % len(locs)]
        sweet = sweets[i % len(sweets)]
        out.append(
            f"{loc}，{t[0]}深扩·{i}。你想起她{sweet}，当时你笑她幼稚，现在不笑。"
            f"发送失败之后，红色感叹号还在，像某种只有你能看见的封印。"
            f"警察空白卡片：找到了吗，你说小路，他划掉，别写太像故事。"
            f"电信详单23:17只有数据心跳，像链在换头。柜员说别问我，问就得写工单。"
            f"二层甜度：关心，但不告白，告白会把路压塌。好是同桌，是作业、便当和袖口。"
            f"线索：三颗糖，走一回少一颗，别一次吃完。编目簿待定，格子没有嘴，只有名字。"
            f"你不结案，你等，等发送成功，等第三排靠窗不再空。逗号后面还有{t[2]}。"
            f"甜的东西要沉，沉住了，比较不容易飘进河里，也不容易被报站冲走。"
        )
    return out
